//! Real-world OFD conformance tests.
//!
//! These tests validate that `easyofd` can parse authentic OFD files produced
//! by other implementations (not generated by our own writer).  The fixtures
//! come from the [ofdrw](https://github.com/ofdrw/ofdrw) open-source project
//! and represent real Chinese electronic documents including invoices and
//! notarial certificates.
//!
//! ## Fixture provenance
//!
//! | Fixture                | Source repo      | Path in repo                                       | Size     | SHA-256 (first 12) |
//! |------------------------|------------------|----------------------------------------------------|----------|---------------------|
//! | `simple_1.ofd`         | ofdrw/ofdrw      | ofdrw-reader/.../helloworld.ofd                    | 1,652 B  | `edaf7b227ebf`      |
//! | `simple_2.ofd`         | ofdrw/ofdrw      | ofdrw-reader/.../chineseDir.ofd                    | 2,097 B  | `c6defec84b24`      |
//! | `multi_page_image.ofd` | ofdrw/ofdrw      | ofdrw-converter/.../999.ofd                        | 29,752 B | `a2b9080ae351`      |
//! | `signed.ofd`           | ofdrw/ofdrw      | ofdrw-sign/.../signedFile.ofd                      | 14,095 B | `bff244b1133a`      |
//! | `with_table.ofd`       | ofdrw/ofdrw      | ofdrw-reader/.../发票示例.ofd                       | 46,091 B | `757c576d18e5`      |
//!
//! All files are < 50 KB and sourced from publicly available test resources.
//!
//! ## Reader resource resolution
//!
//! The reader's `parse_document_resources` now correctly honours the
//! `BaseLoc` attribute on `<ofd:Res>` per GB/T 33190-2016.
//! All fixtures, including those with embedded images stored under a
//! `Res/` subdirectory, should parse successfully.

use std::path::{Path, PathBuf};

use easyofd_core::ContentObject;
use easyofd_reader::OfdReader;

// ─── Helpers ─────────────────────────────────────────────────────────────────

/// Path to the `tests/fixtures/real_ofd/` directory at the workspace root.
fn fixture_dir() -> PathBuf {
    let manifest = std::env::var("CARGO_MANIFEST_DIR").unwrap();
    Path::new(&manifest)
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .join("tests")
        .join("fixtures")
        .join("real_ofd")
}

fn fixture_path(name: &str) -> PathBuf {
    fixture_dir().join(name)
}

/// Guard: skip the test when the fixture directory does not exist (e.g. CI
/// without the fixture download step).
fn require_fixtures() -> PathBuf {
    let dir = fixture_dir();
    assert!(
        dir.exists(),
        "Fixture directory does not exist: {}\n\
         Run the fixture download step or create the directory with real OFD files.",
        dir.display()
    );
    dir
}

// ─── Smoke tests: every fixture without embedded resources must parse ────────

/// Parse all real-world OFD fixtures that do not depend on `BaseLoc`-aware
/// resource resolution (i.e. files with no embedded images/binary resources).
#[test]
fn real_ofd_simple_fixtures_parse() {
    let dir = require_fixtures();

    // Only test fixtures that are known to parse without the BaseLoc issue.
    let simple_fixtures = ["simple_1.ofd", "simple_2.ofd"];
    for name in &simple_fixtures {
        let path = dir.join(name);
        if !path.exists() {
            eprintln!("SKIP: {name} not found in {}", dir.display());
            continue;
        }
        let reader = OfdReader::open(&path)
            .unwrap_or_else(|e| panic!("failed to parse {}: {e}", path.display()));
        assert!(
            reader.page_count() > 0,
            "{name}: expected at least 1 page, got 0"
        );
    }
}

/// Verify that ALL fixtures can at least be opened as valid ZIP archives,
/// even if the reader fails on resource resolution.
#[test]
fn real_ofd_all_fixtures_are_valid_zip() {
    let dir = require_fixtures();
    let entries: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|ext| ext == "ofd"))
        .collect();

    assert!(
        !entries.is_empty(),
        "no .ofd fixtures found in {}",
        dir.display()
    );

    for path in &entries {
        let data =
            std::fs::read(path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        let cursor = std::io::Cursor::new(&data[..]);
        zip::ZipArchive::new(cursor)
            .unwrap_or_else(|e| panic!("{} is not a valid ZIP: {e}", path.display()));
    }
}

// ─── Individual fixture tests ────────────────────────────────────────────────

/// `simple_1.ofd` — minimal single-page OFD created by ofdrw.
///
/// Expected structure:
/// - 1 page, 210 x 297 mm
/// - Text content (Chinese)
#[test]
fn simple_1_ofd_is_readable() {
    let path = fixture_path("simple_1.ofd");
    let reader = OfdReader::open(&path)
        .unwrap_or_else(|e| panic!("failed to parse {}: {e}", path.display()));

    assert_eq!(reader.page_count(), 1, "expected exactly 1 page");

    let text = reader.extract_all_text();
    assert!(
        !text.trim().is_empty(),
        "simple_1.ofd should contain extractable text"
    );
}

