/// `multi_page_image.ofd` — 5-page invoice document with embedded images.
///
/// Expected structure:
/// - 5 pages (Page_0 through Page_4)
/// - At least one page contains an `ImageObject` (a QR code PNG)
///
/// `multi_page_image.ofd` — 5-page invoice document with embedded images.
///
/// Expected structure:
/// - 5 pages (Page_0 through Page_4)
/// - At least one page contains an `ImageObject` (a QR code PNG)
///
/// Resource path resolution now correctly honours `BaseLoc="Res"` on the
/// `<ofd:Res>` element, so `qrcode.png` resolves to `Doc_0/Res/qrcode.png`.
#[test]
fn multi_page_image_ofd_is_readable() {
    let path = fixture_path("multi_page_image.ofd");
    let reader = OfdReader::open(&path)
        .unwrap_or_else(|e| panic!("failed to parse {}: {e}", path.display()));

    assert!(
        reader.page_count() >= 2,
        "expected at least 2 pages, got {}",
        reader.page_count()
    );

    let has_image = reader.pages().iter().any(|page| {
        page.content
            .iter()
            .any(|c| matches!(c, ContentObject::Image(_)))
    });
    assert!(
        has_image,
        "multi_page_image.ofd should contain at least one ImageObject"
    );
}

