/// Verify that `read_signature` can locate and parse the signature structure
/// in `signed.ofd`.
///
/// Current behaviour: the function looks for `Doc_0/Signs/Signature.xml`
/// directly, but real OFD files store signatures in subdirectories
/// (`Sign_0/Signature.xml`) referenced via `Signatures.xml`.  The test
/// therefore asserts that the function returns either Ok (if the reader is
/// fixed to follow the indirection) or the expected "签名文件不存在" error.
#[test]
fn signed_ofd_signature_is_parseable() {
    let path = fixture_path("signed.ofd");

    let result = easyofd_signature::read_signature(&path);

    match result {
        Ok(_) => {
            // Signature was successfully parsed — great!
        }
        Err(e) => {
            let msg = e.to_string();
            assert!(
                msg.contains("签名文件不存在") || msg.contains("Signature"),
                "unexpected error from read_signature: {e}"
            );
        }
    }
}

