// ─── Round-trip: read → write → read ────────────────────────────────────────

/// Verify that a real OFD survives a read→write→read round-trip without losing
/// its page count.  This is a minimal fidelity check; full content comparison
/// is beyond the scope of these conformance tests.
#[test]
fn simple_1_roundtrip_preserves_page_count() {
    use easyofd_writer::OfdWriter;

    let path = fixture_path("simple_1.ofd");
    let reader = OfdReader::open(&path)
        .unwrap_or_else(|e| panic!("failed to parse {}: {e}", path.display()));
    let original_count = reader.page_count();

    // Re-write the parsed pages into a new OFD in memory.
    let mut writer = OfdWriter::new();
    for page in reader.pages() {
        writer.add_page(page.clone());
    }
    let bytes = writer.build().expect("round-trip write should succeed");

    // Read back and verify page count is preserved.
    let reader2 = OfdReader::from_bytes(&bytes).expect("round-trip read should succeed");
    assert_eq!(
        reader2.page_count(),
        original_count,
        "page count changed during round-trip"
    );
}
